SELECT sub.label AS label, sub."value" AS value FROM (SELECT DISTINCT app.application_name AS label, app.cmdb_id as "value" FROM its_application_data app INNER JOIN user_access_review uar on app.cmdb_id = uar.cmdb_id WHERE uar.delete_flag = false
AND (uar.line_manager_review_status = '1' OR uar.bpo_review_status = '1')
AND (uar.line_manager_review_status = '2' AND uar.bpo_review_status = '2')
and uar.it_code_of_user =#{itCodeOfUser}
and uar.final_review_decision =#{finalReviewDecision}
ORDER BY label ) AS sub
